import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.host.sqlite.*;
import io.github.diodeme.ji.ai.*;
import java.nio.file.*;
import java.time.*;
var dir = Files.createTempDirectory("ji-stage6-accept-retention-");
var db = dir.resolve("host.db");
var store = new PersistentHostStore(new SqliteHostStorePersistence(db));
var model = new ModelRef("profile", "model");
var first = store.createSession("create-1", "hash-1", "session-1", model, "workspace", Instant.EPOCH);
var revision = store.load("session-1").orElseThrow().revision();
var trashed = store.trash("session-1", revision, Instant.EPOCH.plusSeconds(1));
var second = store.createSession("create-2", "hash-2", "session-1", model, "workspace", Instant.EPOCH.plusSeconds(2));
System.out.println("SECOND_CREATED=" + second.created() + " LOAD_PRESENT=" + store.load("session-1").isPresent());
store.close();
var reopened = new PersistentHostStore(new SqliteHostStorePersistence(db));
var retry = reopened.createSession("create-2", "hash-2", "session-1", model, "workspace", Instant.EPOCH.plusSeconds(3));
System.out.println("RETRY_CREATED=" + retry.created() + " LOAD_PRESENT=" + reopened.load("session-1").isPresent());
reopened.close();
Files.walk(dir).sorted(java.util.Comparator.reverseOrder()).forEach(p -> { try { Files.delete(p); } catch (Exception e) { throw new RuntimeException(e); } });
/exit
